(function(){"use strict";window.EDMUND_DSE_LISTENING_2012_TRANSCRIPT=Object.freeze({"partA":{"1":[{"start":0.04,"end":7.08,"speaker":"Narrator","text":"Task 1. You will listen to a meeting at Aberdeen College where people are discussing the College's"},{"start":7.08,"end":17.8,"speaker":"College meeting","text":"new online systems. Listen to the meeting and fill in the missing information in the"},{"start":17.8,"end":23.52,"speaker":"College meeting","text":"question for you as an example. You now have 30 seconds to study the task."},{"start":24.32,"end":28.96,"speaker":"College meeting","text":"At the end of the task, you will have one minute to tidy up your answers."},{"start":60.52,"end":67.67,"speaker":"College meeting","text":"OK, good morning everybody. Thanks for coming to the meeting today. I know today's Saturday"},{"start":68.23,"end":71.75,"speaker":"College meeting","text":"and I'm sure you've got other things to do on a Saturday morning,"},{"start":72.61,"end":77.73,"speaker":"College meeting","text":"but hopefully the meeting will be a short one. Do you two know each other?"},{"start":77.73,"end":80.03,"speaker":"College meeting","text":"No, I don't think so."},{"start":81.23,"end":88.61,"speaker":"College meeting","text":"OK, well, this is Rob Lee. Rob's the College Technician, so he can advise us on technical matters."},{"start":89.49,"end":89.89,"speaker":"College meeting","text":"And Rob?"},{"start":90.17,"end":90.53,"speaker":"College meeting","text":"Hi."},{"start":91.25,"end":91.35,"speaker":"College meeting","text":"Hi."},{"start":92.05,"end":96.59,"speaker":"College meeting","text":"Yeah. And Rob, I think you know Cherry, our student president."},{"start":97.84,"end":105.76,"speaker":"College meeting","text":"OK. Right, so as I said in my email, I wanted to discuss what needs to be done to improve"},{"start":105.76,"end":112.38,"speaker":"College meeting","text":"the College's online systems. So maybe we could start with the College website."},{"start":113.44,"end":115.84,"speaker":"College meeting","text":"Any comments from students about the website?"},{"start":116.42,"end":123.88,"speaker":"College meeting","text":"Well, the first thing I've written here about the website is that it's like boring."},{"start":125.12,"end":127.12,"speaker":"College meeting","text":"Students are always saying that."},{"start":127.8,"end":131.6,"speaker":"College meeting","text":"Yeah, I agree with Cherry actually. It's a bit boring."},{"start":131.6,"end":136.08,"speaker":"College meeting","text":"I think the thing that I would add would be that it's not user friendly."},{"start":137.2,"end":140.96,"speaker":"College meeting","text":"Yeah, I'd agree. It certainly isn't user friendly."},{"start":142.49,"end":148.15,"speaker":"College meeting","text":"What about the other services, like the intranet system for teachers?"},{"start":148.81,"end":153.25,"speaker":"College meeting","text":"Intranet? Is that like where the teachers can communicate with each other?"},{"start":153.83,"end":159.71,"speaker":"College meeting","text":"Yeah, the teachers can use the intranet to send files as well, like documents,"},{"start":160.21,"end":162.43,"speaker":"College meeting","text":"pictures, video clips."},{"start":163.31,"end":165.59,"speaker":"College meeting","text":"Why don't they just use their email?"},{"start":166.74,"end":173.64,"speaker":"College meeting","text":"Because it isn't secure. You know, it's not safe to send files like that."},{"start":174.4,"end":180.04,"speaker":"College meeting","text":"And the intranet has the advantage that it's secure because it's protected by the College's firewall."},{"start":181.48,"end":188.9,"speaker":"College meeting","text":"OK, let's move on. What kinds of things would we like to see available online from the new system?"},{"start":190.59,"end":196.41,"speaker":"College meeting","text":"Well, I think a social network. You know, something like Facebook."},{"start":197.73,"end":203.91,"speaker":"College meeting","text":"Maybe a place where we could chat online about school stuff with schoolmates and teachers."},{"start":204.91,"end":210.53,"speaker":"College meeting","text":"Wait, so you would want teachers to be able to go to this social network as well?"},{"start":211.27,"end":212.65,"speaker":"College meeting","text":"As well as students, I mean."},{"start":213.07,"end":214.07,"speaker":"College meeting","text":"Sure, why not?"},{"start":215.01,"end":218.35,"speaker":"College meeting","text":"OK, well, that's one idea. What else?"},{"start":219.03,"end":222.37,"speaker":"College meeting","text":"How about an online market?"},{"start":222.99,"end":225.99,"speaker":"College meeting","text":"What? Like for people to buy and sell things?"},{"start":226.41,"end":233.81,"speaker":"College meeting","text":"Yeah, a market. I was thinking, you know, we could like sell things like our old textbooks"},{"start":234.39,"end":237.29,"speaker":"College meeting","text":"and students in lower forms could buy them."},{"start":238.2,"end":240.95,"speaker":"College meeting","text":"Sounds good. I think that would work."},{"start":241.92,"end":246.42,"speaker":"College meeting","text":"Right, OK, let's move on to the action we need to take."},{"start":247.24,"end":251.46,"speaker":"College meeting","text":"First, the website. Can you be responsible for that, Rob?"},{"start":252.26,"end":255.7,"speaker":"College meeting","text":"For what? The redesign of the website."},{"start":256.54,"end":261.12,"speaker":"College meeting","text":"Well, my programming skills. I mean, they're pretty basic."},{"start":262.82,"end":266.06,"speaker":"College meeting","text":"But I know a web designer, so I could contact him."},{"start":266.52,"end":268.88,"speaker":"College meeting","text":"Maybe, you know, to give us a price."},{"start":269.46,"end":273.7,"speaker":"College meeting","text":"OK, right. So you contact the web designer then, Rob."},{"start":274.4,"end":276.82,"speaker":"College meeting","text":"How about the other systems we talked about?"},{"start":277.46,"end":280.8,"speaker":"College meeting","text":"Well, why don't I carry out a survey of the students"},{"start":281.34,"end":284.88,"speaker":"College meeting","text":"to see what it is they want from our online systems?"},{"start":285.88,"end":290.88,"speaker":"College meeting","text":"Great idea, Cherry. It's really important that we get the students' views on this."},{"start":291.91,"end":295.39,"speaker":"College meeting","text":"I think a survey of the students is an excellent idea."},{"start":296.11,"end":298.83,"speaker":"College meeting","text":"So, yeah, you can do that, Cherry."},{"start":299.07,"end":299.49,"speaker":"College meeting","text":"Fine."},{"start":300.27,"end":302.11,"speaker":"College meeting","text":"And I'll do the same with the teachers."},{"start":302.11,"end":305.49,"speaker":"College meeting","text":"We need to get their input as well."},{"start":306.6,"end":307.74,"speaker":"College meeting","text":"So a survey's good."},{"start":309.15,"end":312.81,"speaker":"College meeting","text":"Right, OK, so that's about all we can do today."},{"start":314.02,"end":316.84,"speaker":"College meeting","text":"Let's meet again next week, at the same time."},{"start":317.28,"end":321.56,"speaker":"College meeting","text":"I'm sorry. I think I'll need more time than a week."},{"start":323.12,"end":324.82,"speaker":"College meeting","text":"Can we meet in two weeks' time?"},{"start":325.82,"end":327.88,"speaker":"College meeting","text":"OK, two weeks it is then."},{"start":329.02,"end":330.98,"speaker":"Narrator","text":"That is the end of task one."},{"start":330.98,"end":334.48,"speaker":"Narrator","text":"You now have one minute to tidy up your answers."}],"2":[{"start":0,"end":0.46,"speaker":"Narrator","text":"Task two."},{"start":1.61,"end":4.31,"speaker":"Dannie Wan","text":"You will listen to a presentation by Danny Won"},{"start":4.31,"end":7.77,"speaker":"Dannie Wan","text":"describing some of the features of the new website"},{"start":7.77,"end":11.45,"speaker":"Dannie Wan","text":"to Mr Law, Rob Lee and Cherry Tam."},{"start":12.27,"end":16.15,"speaker":"Narrator","text":"Listen to the presentation and fill in the missing information"},{"start":16.15,"end":19.27,"speaker":"Dannie Wan","text":"in the spaces provided on the website pages."},{"start":20.11,"end":22.73,"speaker":"Dannie Wan","text":"One has been done for you as an example."},{"start":24.06,"end":27.14,"speaker":"Narrator","text":"You now have 30 seconds to study the task."},{"start":27.96,"end":30.8,"speaker":"Dannie Wan","text":"At the end of the task, you will have one minute"},{"start":30.8,"end":32.52,"speaker":"Dannie Wan","text":"to tidy up your answers."},{"start":65.03,"end":68.61,"speaker":"Dannie Wan","text":"OK, if you're ready, Danny, you can start now."},{"start":69.31,"end":69.99,"speaker":"Dannie Wan","text":"Thanks, Rob."},{"start":70.63,"end":74.15,"speaker":"Dannie Wan","text":"And thanks to Mr Law and Cherry for coming to my presentation."},{"start":75.24,"end":78.24,"speaker":"Dannie Wan","text":"I'm going to show you our first draft design"},{"start":78.24,"end":80.14,"speaker":"Dannie Wan","text":"for the new college website."},{"start":81,"end":84.2,"speaker":"Dannie Wan","text":"It's still a bit rough, but I hope you can get the idea."},{"start":85.5,"end":89.64,"speaker":"Dannie Wan","text":"To start with, on the screen here, you can see the homepage"},{"start":89.64,"end":93.84,"speaker":"Dannie Wan","text":"of the website with the college logo in the top left corner"},{"start":94.6,"end":96.52,"speaker":"Dannie Wan","text":"and the name of the college, of course."},{"start":97.65,"end":100.61,"speaker":"Dannie Wan","text":"Then on the right is a box labelled search"},{"start":101.05,"end":103.49,"speaker":"Dannie Wan","text":"for people to search the site using keywords."},{"start":104.59,"end":107.17,"speaker":"Dannie Wan","text":"And they can search anywhere in the site?"},{"start":107.77,"end":109.23,"speaker":"Dannie Wan","text":"Yeah, that's right, Mr Law."},{"start":110.07,"end":114.09,"speaker":"Dannie Wan","text":"OK, so on the next row down from left to right,"},{"start":114.09,"end":118.01,"speaker":"Dannie Wan","text":"we have the tabs for the individual pages of the website."},{"start":118.99,"end":121.69,"speaker":"Dannie Wan","text":"The homepage, which is the one we're on now."},{"start":122.51,"end":124.71,"speaker":"Dannie Wan","text":"Then there's a page called About Us,"},{"start":125.55,"end":127.93,"speaker":"Dannie Wan","text":"where you have all the information about the college,"},{"start":128.73,"end":133.69,"speaker":"Dannie Wan","text":"including its history, its mission, the staff, and so on."},{"start":134.66,"end":138.88,"speaker":"Dannie Wan","text":"And then we have the Students page, which I'll come to later."},{"start":139.65,"end":142.63,"speaker":"Dannie Wan","text":"A page for parents, so that they can get information"},{"start":142.63,"end":144.71,"speaker":"Dannie Wan","text":"about the college from their perspective."},{"start":145.9,"end":149.34,"speaker":"Dannie Wan","text":"Then we have a Subjects page, which will include things"},{"start":149.34,"end":150.62,"speaker":"Dannie Wan","text":"like the course outlines."},{"start":151.32,"end":154.86,"speaker":"Dannie Wan","text":"And finally, there's a page for extracurricular activities."},{"start":155.56,"end":158.12,"speaker":"Dannie Wan","text":"Ooh, they're nice photos below that."},{"start":159,"end":161.8,"speaker":"Dannie Wan","text":"Yeah, I just used ones from the old website."},{"start":162.6,"end":167.08,"speaker":"Dannie Wan","text":"You can see three just now, but it's actually a gallery of 12,"},{"start":167.42,"end":169.52,"speaker":"Dannie Wan","text":"which will change every five seconds."},{"start":170,"end":172.72,"speaker":"Dannie Wan","text":"The captions below will change as well."},{"start":173.66,"end":179.04,"speaker":"Dannie Wan","text":"At present, I've put up three photos and called them Sports Day."},{"start":180.36,"end":184.34,"speaker":"Dannie Wan","text":"The one in the middle, I've called Study at AC."},{"start":185.79,"end":188.91,"speaker":"Dannie Wan","text":"And the other one is A Recent Visit."},{"start":190.26,"end":193.92,"speaker":"Dannie Wan","text":"Is that you, Cherry, in the Study at AC photo?"},{"start":194.48,"end":197.26,"speaker":"Dannie Wan","text":"Yeah, that's me holding up my hand."},{"start":197.9,"end":199.2,"speaker":"Dannie Wan","text":"Right, moving on."},{"start":200.34,"end":204.97,"speaker":"Dannie Wan","text":"Now, on the left of the page, left of the welcome message"},{"start":204.97,"end":209.15,"speaker":"Dannie Wan","text":"from the principal, you can see three separate boxes."},{"start":210.44,"end":215.06,"speaker":"Dannie Wan","text":"These are for important information that you want your visitors to see first."},{"start":216.44,"end":219.4,"speaker":"Dannie Wan","text":"The first is for upcoming events."},{"start":221.01,"end":225.53,"speaker":"Dannie Wan","text":"People can simply click on the link and go to the interactive calendar."},{"start":227.21,"end":230.85,"speaker":"Dannie Wan","text":"Then next is the Latest News section."},{"start":232.15,"end":235.57,"speaker":"Dannie Wan","text":"You can see that I've added in a link to a story."},{"start":236.53,"end":238.15,"speaker":"Dannie Wan","text":"College Wins Cup?"},{"start":238.93,"end":242.05,"speaker":"Dannie Wan","text":"Yes, I just made that up as a demonstration."},{"start":242.75,"end":248.35,"speaker":"Dannie Wan","text":"Actually, the college has just won the District Handball Cup, so it's right."},{"start":249.59,"end":249.99,"speaker":"Dannie Wan","text":"Excellent."},{"start":250.65,"end":252.21,"speaker":"Dannie Wan","text":"Right, where was I?"},{"start":252.99,"end":254.37,"speaker":"Dannie Wan","text":"Right, the next one."},{"start":255.09,"end":257.21,"speaker":"Dannie Wan","text":"Well, again, this is just a demo."},{"start":257.79,"end":260.21,"speaker":"Dannie Wan","text":"I called this one Have Your Say."},{"start":261.42,"end":267.46,"speaker":"Dannie Wan","text":"It could be a link to a place where students and teachers can make comments on the college."},{"start":268.9,"end":270.82,"speaker":"Dannie Wan","text":"Hmm, Have Your Say."},{"start":271.42,"end":277.5,"speaker":"Dannie Wan","text":"I like the sound of it, but I'm not sure I'd like what the students might post there."},{"start":278,"end":279.46,"speaker":"Dannie Wan","text":"Hmm, okay."},{"start":280.36,"end":282.18,"speaker":"Dannie Wan","text":"And that's about it for the home page."},{"start":283.4,"end":283.7,"speaker":"Dannie Wan","text":"Good."},{"start":284.78,"end":287.9,"speaker":"Dannie Wan","text":"Have you had time to work on any of the other pages?"},{"start":288.68,"end":289.82,"speaker":"Dannie Wan","text":"Yeah, okay."},{"start":290.54,"end":292.9,"speaker":"Dannie Wan","text":"We've been working on the students page."},{"start":293.5,"end":294.28,"speaker":"Dannie Wan","text":"Just a second."},{"start":295.76,"end":296.56,"speaker":"Dannie Wan","text":"So here it is."},{"start":297.12,"end":298.12,"speaker":"Dannie Wan","text":"The students page."},{"start":299.39,"end":303.99,"speaker":"Dannie Wan","text":"There will be all the same things at the top of the page, as on the home page."},{"start":304.79,"end":307.19,"speaker":"Dannie Wan","text":"So I haven't included them on the demo."},{"start":308.43,"end":311.83,"speaker":"Dannie Wan","text":"Oh, you can see three different photos here."},{"start":312.17,"end":312.81,"speaker":"Dannie Wan","text":"Okay."},{"start":313.75,"end":317.87,"speaker":"Dannie Wan","text":"The difference is in the menus on the left side of the page,"},{"start":318.51,"end":322.93,"speaker":"Dannie Wan","text":"where you can see that we have various links to places in the site"},{"start":323.46,"end":325.67,"speaker":"Dannie Wan","text":"that will be of interest to the students."},{"start":327.08,"end":329.88,"speaker":"Dannie Wan","text":"So we have transport at the top of the list."},{"start":331.18,"end":331.38,"speaker":"Dannie Wan","text":"Good."},{"start":331.86,"end":335.74,"speaker":"Dannie Wan","text":"If the students can't get here, then you can't teach them very much, can you?"},{"start":336.12,"end":337.32,"speaker":"Dannie Wan","text":"That's what I always say."},{"start":339.95,"end":342.23,"speaker":"Dannie Wan","text":"Yes, so transport."},{"start":343.53,"end":345.55,"speaker":"Dannie Wan","text":"And then we have canteen."},{"start":346.73,"end":349.17,"speaker":"Dannie Wan","text":"The next one's something quite new."},{"start":349.93,"end":355.79,"speaker":"Dannie Wan","text":"And this is the Acquaint, the social networking facility that we have introduced."},{"start":356.97,"end":360.77,"speaker":"Dannie Wan","text":"It's still in production, so we can't show it to you yet."},{"start":361.57,"end":364.53,"speaker":"Dannie Wan","text":"But users will be able to access it from here."},{"start":365.71,"end":369.51,"speaker":"Dannie Wan","text":"I've just included some examples of what you could do with Acquaint."},{"start":370.46,"end":373.36,"speaker":"Dannie Wan","text":"The examples I've put here are share content,"},{"start":374.77,"end":375.87,"speaker":"Dannie Wan","text":"meet new friends,"},{"start":376.77,"end":381.11,"speaker":"Dannie Wan","text":"and maybe the most important, build relationships."},{"start":382.46,"end":383.32,"speaker":"Dannie Wan","text":"Yep, looks good."},{"start":383.86,"end":385.9,"speaker":"Dannie Wan","text":"That last one, build relationships."},{"start":386.78,"end":390.6,"speaker":"Dannie Wan","text":"It'd be really good if we could use the website to build relationships,"},{"start":391.3,"end":396.22,"speaker":"Dannie Wan","text":"you know, between students and students and between students and teachers."},{"start":397.18,"end":397.46,"speaker":"Dannie Wan","text":"Yeah."},{"start":398.06,"end":401.48,"speaker":"Dannie Wan","text":"So the other major thing we've included on the menu,"},{"start":401.76,"end":405.04,"speaker":"Dannie Wan","text":"on the students page, is academe."},{"start":405.04,"end":408.26,"speaker":"Dannie Wan","text":"The new learning management system."},{"start":409.24,"end":410.08,"speaker":"Dannie Wan","text":"Acco..."},{"start":410.08,"end":410.52,"speaker":"Dannie Wan","text":"What?"},{"start":412.02,"end":412.7,"speaker":"Dannie Wan","text":"Accadeen."},{"start":413.42,"end":418.06,"speaker":"Dannie Wan","text":"A, C, A, D, E, M, E."},{"start":419.34,"end":422.92,"speaker":"Dannie Wan","text":"It means the academic or learning environment,"},{"start":423.44,"end":427.36,"speaker":"Dannie Wan","text":"and also begins with AC for Aberdeen College."},{"start":427.82,"end":429.12,"speaker":"Dannie Wan","text":"Oh yeah, very good."},{"start":429.92,"end":434.92,"speaker":"Dannie Wan","text":"And again, we're working on that and hope to have it ready for you to see soon."},{"start":436.1,"end":439.78,"speaker":"Dannie Wan","text":"So after academe, we have a link to the library,"},{"start":440.36,"end":443.58,"speaker":"Dannie Wan","text":"and then two links are to the dreaded examinations."},{"start":445.11,"end":449.69,"speaker":"Dannie Wan","text":"We have separate links to exam information and exam results."},{"start":450.55,"end":450.67,"speaker":"Dannie Wan","text":"Yeah."},{"start":450.99,"end":453.23,"speaker":"Dannie Wan","text":"Well, exams are on everybody's minds."},{"start":453.91,"end":454.61,"speaker":"Dannie Wan","text":"So, good."},{"start":455.05,"end":455.29,"speaker":"Dannie Wan","text":"Yeah."},{"start":455.85,"end":457.81,"speaker":"Dannie Wan","text":"We can provide the information here."},{"start":459.02,"end":461.96,"speaker":"Dannie Wan","text":"I don't know what you're looking so worried about, Cherry."},{"start":462.49,"end":466.82,"speaker":"Dannie Wan","text":"As far as I can gather, you do pretty well in examinations anyway."},{"start":467.16,"end":469.28,"speaker":"Dannie Wan","text":"Well, it depends on the subject."},{"start":470.02,"end":471.86,"speaker":"Dannie Wan","text":"And that's about it so far."},{"start":473.22,"end":475.04,"speaker":"Narrator","text":"That is the end of task two."},{"start":476.17,"end":479.27,"speaker":"Narrator","text":"You now have one minute to tidy up your answers."}],"3":[{"start":0.01,"end":0.67,"speaker":"Narrator","text":"Task three."},{"start":1.98,"end":5.64,"speaker":"Students and Cherry","text":"Cherry is now talking to a group of form five and six students"},{"start":5.64,"end":10.4,"speaker":"Students and Cherry","text":"about the college's online systems and issues about studying online."},{"start":11.44,"end":15.22,"speaker":"Narrator","text":"Complete the information in the spaces provided as you listen."},{"start":16.18,"end":18.42,"speaker":"Students and Cherry","text":"One has been done for you as an example."},{"start":19.54,"end":22.5,"speaker":"Narrator","text":"You now have 30 seconds to study the task."},{"start":23.41,"end":28.75,"speaker":"Students and Cherry","text":"At the end of the task, you will have one and a half minutes to tidy up your answers."},{"start":60,"end":60.38,"speaker":"Students and Cherry","text":"Okay."},{"start":60.6,"end":61.8,"speaker":"Students and Cherry","text":"Thanks everyone for coming."},{"start":62.68,"end":64.68,"speaker":"Students and Cherry","text":"I hope you don't mind me recording this."},{"start":65.79,"end":68.67,"speaker":"Students and Cherry","text":"Perhaps we can start with everybody saying a little bit"},{"start":68.67,"end":71.93,"speaker":"Students and Cherry","text":"about what they think the main issues are about."},{"start":72.35,"end":75.99,"speaker":"Students and Cherry","text":"You know, studying online at Aberdeen College."},{"start":76.64,"end":77.2,"speaker":"Students and Cherry","text":"Right."},{"start":77.62,"end":78.64,"speaker":"Students and Cherry","text":"Well, I can start."},{"start":79.44,"end":83.78,"speaker":"Students and Cherry","text":"I think I should say from the outset that there's no way you can replace real learning"},{"start":83.78,"end":88.08,"speaker":"Students and Cherry","text":"in the classroom with reading from websites and watching videos on YouTube."},{"start":88.86,"end":89.02,"speaker":"Students and Cherry","text":"Sorry."},{"start":89.52,"end":90.86,"speaker":"Students and Cherry","text":"Can you introduce yourself?"},{"start":91.42,"end":92.1,"speaker":"Students and Cherry","text":"Oh, sorry."},{"start":92.62,"end":94.08,"speaker":"Students and Cherry","text":"I'm Grace Yao from 5C."},{"start":94.44,"end":94.74,"speaker":"Students and Cherry","text":"Okay."},{"start":95.22,"end":96.86,"speaker":"Students and Cherry","text":"Grace, please go on."},{"start":96.86,"end":102.9,"speaker":"Students and Cherry","text":"You were saying that learning online can't replace classroom learning."},{"start":103.84,"end":103.86,"speaker":"Students and Cherry","text":"Yeah."},{"start":104.4,"end":107.42,"speaker":"Students and Cherry","text":"I mean, learning is meant to be interactive, right?"},{"start":107.96,"end":110.68,"speaker":"Students and Cherry","text":"We learn from teachers and we learn from classmates."},{"start":111.32,"end":114.94,"speaker":"Students and Cherry","text":"We learn by listening to people who know more than us like the teacher"},{"start":114.94,"end":118.18,"speaker":"Students and Cherry","text":"and by talking to people who are learning along with us."},{"start":118.78,"end":123.56,"speaker":"Students and Cherry","text":"We also learn by doing things like in science, we learn by doing experiments"},{"start":123.56,"end":126.28,"speaker":"Students and Cherry","text":"and in art, we learn by creating things."},{"start":126.28,"end":129.34,"speaker":"Students and Cherry","text":"You can create things on computers as well."},{"start":130.41,"end":132.45,"speaker":"Students and Cherry","text":"Yeah, but it's not the same dough, is it?"},{"start":132.93,"end":137.09,"speaker":"Students and Cherry","text":"I think computers and iPads and iPhones are brilliant for playing games"},{"start":137.09,"end":138.95,"speaker":"Students and Cherry","text":"and chatting with our friends and stuff."},{"start":139.37,"end":141.31,"speaker":"Students and Cherry","text":"But it's not real learning, is it?"},{"start":141.95,"end":142.37,"speaker":"Students and Cherry","text":"Okay."},{"start":142.75,"end":146.61,"speaker":"Students and Cherry","text":"Maybe you can tell us more about what you think."},{"start":147.23,"end":148.43,"speaker":"Students and Cherry","text":"What's your name again?"},{"start":149.03,"end":149.31,"speaker":"Students and Cherry","text":"Me."},{"start":149.97,"end":151.55,"speaker":"Students and Cherry","text":"My name's Icarus Liu."},{"start":152.41,"end":152.91,"speaker":"Students and Cherry","text":"Icarus."},{"start":153.29,"end":154.67,"speaker":"Students and Cherry","text":"That's an unusual name."},{"start":155.07,"end":156.03,"speaker":"Students and Cherry","text":"How do you spell that?"},{"start":156.31,"end":163.65,"speaker":"Students and Cherry","text":"I, C, A, R, U, S, Icarus, U, L, I, U."},{"start":164.05,"end":165.09,"speaker":"Students and Cherry","text":"Okay, Icarus."},{"start":165.49,"end":166.29,"speaker":"Students and Cherry","text":"What do you think?"},{"start":167.01,"end":174.15,"speaker":"Students and Cherry","text":"Well, I mean, we all have computers at home and a lot of students have laptops as well."},{"start":174.81,"end":178.03,"speaker":"Students and Cherry","text":"So we can all access online learning materials."},{"start":178.83,"end":184.33,"speaker":"Students and Cherry","text":"So I think we should be using that environment to learn much more than we do."},{"start":184.33,"end":188.25,"speaker":"Students and Cherry","text":"To be honest, I learn more at home than at school."},{"start":189.25,"end":191.65,"speaker":"Students and Cherry","text":"That's quite a bold statement there, Icarus."},{"start":192.13,"end":192.43,"speaker":"Students and Cherry","text":"Yeah."},{"start":193.07,"end":196.33,"speaker":"Students and Cherry","text":"I mean, there's lots of ways we can learn online."},{"start":196.99,"end":200.09,"speaker":"Students and Cherry","text":"We can use video conferencing to talk to people."},{"start":200.75,"end":203.33,"speaker":"Students and Cherry","text":"And we can use all kinds of creative software."},{"start":204.01,"end":206.97,"speaker":"Students and Cherry","text":"What do you mean, creative software?"},{"start":208.57,"end":213.37,"speaker":"Students and Cherry","text":"Creative software, you know, to draw or design things."},{"start":213.37,"end":214.29,"speaker":"Students and Cherry","text":"Oh, right."},{"start":214.59,"end":214.85,"speaker":"Students and Cherry","text":"Okay."},{"start":215.73,"end":216.03,"speaker":"Students and Cherry","text":"Right."},{"start":216.33,"end":217.65,"speaker":"Students and Cherry","text":"Maybe I'll ask somebody else."},{"start":218.83,"end":219.41,"speaker":"Students and Cherry","text":"Yes."},{"start":220.19,"end":220.43,"speaker":"Students and Cherry","text":"Yeah."},{"start":220.75,"end":223.67,"speaker":"Students and Cherry","text":"Hi, I'm Michael Ong from 6B."},{"start":224.51,"end":228.29,"speaker":"Students and Cherry","text":"Obviously, I haven't thought about this as much as grace and Icarus."},{"start":229.03,"end":231.33,"speaker":"Students and Cherry","text":"I'm still not sure about all this really."},{"start":232.19,"end":236.51,"speaker":"Students and Cherry","text":"I mean, I can now be reading, you know, a book or whatever."},{"start":237.23,"end":242.35,"speaker":"Students and Cherry","text":"And I can look up any words I don't know on an online dictionary instantly"},{"start":242.35,"end":243.71,"speaker":"Students and Cherry","text":"and learn that way."},{"start":244.59,"end":248.17,"speaker":"Students and Cherry","text":"But I still want to share what I've learned with my classmates as well"},{"start":248.83,"end":251.55,"speaker":"Students and Cherry","text":"and get my teachers advised on how to use it."},{"start":252.46,"end":252.66,"speaker":"Students and Cherry","text":"Okay."},{"start":253.22,"end":257.3,"speaker":"Students and Cherry","text":"I want to switch the focus of our discussion a little now"},{"start":257.3,"end":260.92,"speaker":"Students and Cherry","text":"and ask how you'd feel about having a facility"},{"start":261.62,"end":266.06,"speaker":"Students and Cherry","text":"that lets students and teachers communicate with each other."},{"start":266.83,"end":268.71,"speaker":"Students and Cherry","text":"We can do that already through Facebook."},{"start":269.57,"end":271.75,"speaker":"Students and Cherry","text":"Why not just have a college Facebook page?"},{"start":272.61,"end":274.49,"speaker":"Students and Cherry","text":"That's an option we've talked about."},{"start":274.95,"end":276.47,"speaker":"Students and Cherry","text":"Do you think it would be a good idea?"},{"start":277.39,"end":279.43,"speaker":"Students and Cherry","text":"No, I think it's too dangerous."},{"start":280.13,"end":282.81,"speaker":"Students and Cherry","text":"Students are too keen to put themselves on Facebook."},{"start":283.65,"end":287.25,"speaker":"Students and Cherry","text":"They post all sorts of personal stuff like, I don't know,"},{"start":287.53,"end":291.29,"speaker":"Students and Cherry","text":"they put up videos of themselves and they give out their phone number."},{"start":291.79,"end":293.43,"speaker":"Students and Cherry","text":"I just think it's dangerous."},{"start":295.7,"end":296.82,"speaker":"Students and Cherry","text":"Dangerous how, Grace?"},{"start":297.72,"end":301.82,"speaker":"Students and Cherry","text":"Because you don't know who's going to be reading all of this personal stuff."},{"start":302.32,"end":306.32,"speaker":"Students and Cherry","text":"I mean, if you do post your phone number, it's really stupid."},{"start":307.38,"end":310.18,"speaker":"Students and Cherry","text":"Yeah, but you can control who sees your information."},{"start":310.88,"end":311.34,"speaker":"Students and Cherry","text":"I know."},{"start":311.56,"end":312.3,"speaker":"Students and Cherry","text":"I know you can."},{"start":313.02,"end":314.92,"speaker":"Students and Cherry","text":"But a lot of students just don't bother"},{"start":314.92,"end":317.4,"speaker":"Students and Cherry","text":"and they say yes to every friend request,"},{"start":317.94,"end":319.5,"speaker":"Students and Cherry","text":"even if they don't know that person."},{"start":320,"end":321.12,"speaker":"Students and Cherry","text":"Okay, fine."},{"start":321.54,"end":322.78,"speaker":"Students and Cherry","text":"There are always dangers."},{"start":323.46,"end":328.3,"speaker":"Students and Cherry","text":"I would never give out personal information like my home address or whatever."},{"start":328.94,"end":330.38,"speaker":"Students and Cherry","text":"But often people do."},{"start":330.74,"end":331.38,"speaker":"Students and Cherry","text":"That's the point."},{"start":331.82,"end":335.28,"speaker":"Students and Cherry","text":"I think some students are just too eager to make new friends."},{"start":336.14,"end":341.4,"speaker":"Students and Cherry","text":"No, the point is that people need to learn that doing that sort of thing is stupid."},{"start":342.3,"end":342.76,"speaker":"Students and Cherry","text":"Michael?"},{"start":344,"end":346.16,"speaker":"Students and Cherry","text":"I tend to agree with Icarus."},{"start":346.74,"end":351.62,"speaker":"Students and Cherry","text":"Making friends online is one of the great benefits of having an online social network."},{"start":352.26,"end":354.82,"speaker":"Students and Cherry","text":"It's part of the reality of the outside world."},{"start":355.56,"end":357.62,"speaker":"Students and Cherry","text":"The school should get a social network"},{"start":357.62,"end":362.12,"speaker":"Students and Cherry","text":"and then take the opportunity to educate students about the dangers,"},{"start":362.62,"end":365.22,"speaker":"Students and Cherry","text":"not just pretend that the dangers don't exist."},{"start":365.74,"end":366.02,"speaker":"Students and Cherry","text":"Totally."},{"start":366.48,"end":366.72,"speaker":"Students and Cherry","text":"Yeah."},{"start":367.42,"end":371.48,"speaker":"Students and Cherry","text":"Use technology to educate students about the dangers."},{"start":371.9,"end":372.16,"speaker":"Students and Cherry","text":"Yeah."},{"start":373.13,"end":375.27,"speaker":"Narrator","text":"That is the end of task three."},{"start":375.87,"end":379.31,"speaker":"Narrator","text":"You now have one and a half minutes to complete your answers."}],"4":[{"start":0,"end":5.93,"speaker":"Podcast","text":"Cherry and her friend Roland are listening to a podcast about online systems."},{"start":6.59,"end":10.61,"speaker":"Narrator","text":"Complete the information in the spaces provided as you listen."},{"start":11.84,"end":14.5,"speaker":"Podcast","text":"Please note that for the summary of the podcast,"},{"start":15.3,"end":19.18,"speaker":"Podcast","text":"you should use no more than three words to complete each gap."},{"start":20.14,"end":22.62,"speaker":"Narrator","text":"You now have one minute to study the task."},{"start":23.3,"end":27.52,"speaker":"Podcast","text":"At the end of the task, you will have two minutes to tidy up your answers."},{"start":89.76,"end":92.6,"speaker":"Podcast","text":"Do you want to listen to that podcast I was telling you about?"},{"start":93.15,"end":97.72,"speaker":"Podcast","text":"It's by a guy called Jerry Brooker and he talks."},{"start":98.22,"end":105.24,"speaker":"Podcast","text":"He's talking about how what the effect is of social networks on people's use of email."},{"start":106.22,"end":106.26,"speaker":"Podcast","text":"Cool."},{"start":106.58,"end":107.14,"speaker":"Podcast","text":"Let's listen."},{"start":108.09,"end":108.41,"speaker":"Podcast","text":"Okay."},{"start":108.65,"end":109.51,"speaker":"Podcast","text":"Here we go."},{"start":110.49,"end":115.75,"speaker":"Podcast","text":"The idea of email becoming extinct anytime soon may seem silly,"},{"start":115.93,"end":122.13,"speaker":"Podcast","text":"but chances are strong that you used web-based email less in 2011"},{"start":122.83,"end":124.17,"speaker":"Podcast","text":"than in 2010."},{"start":125.2,"end":130.7,"speaker":"Podcast","text":"A recent report, the 2012 US Digital Year in Review"},{"start":131.16,"end":137.28,"speaker":"Podcast","text":"showed that web-based email usage was down for just about every age group under 55"},{"start":137.74,"end":143.46,"speaker":"Podcast","text":"from 2010 to 2011 with the 12 to 17 age group"},{"start":143.46,"end":146.94,"speaker":"Podcast","text":"showing the largest decline at a staggering 59%."},{"start":148.06,"end":153.64,"speaker":"Podcast","text":"Web-based email or webmail refers to email access through a browser."},{"start":154.48,"end":158.8,"speaker":"Podcast","text":"So think Gmail, Hotmail, Yahoo Mail, et cetera,"},{"start":158.94,"end":162.28,"speaker":"Podcast","text":"as the majority of email usage analyzed in this report."},{"start":163.02,"end":167.82,"speaker":"Podcast","text":"This means that the groups of people who make up the majority of internet users"},{"start":167.82,"end":173.6,"speaker":"Podcast","text":"and have the most experience with email are now actually moving away from the medium."},{"start":174.64,"end":179.72,"speaker":"Podcast","text":"The report also noted that email usage among seniors has increased,"},{"start":180.5,"end":184.34,"speaker":"Podcast","text":"which isn't surprising as a larger percentage of older people today"},{"start":184.34,"end":187.62,"speaker":"Podcast","text":"have had more exposure to the web than their predecessors."},{"start":189.06,"end":194.06,"speaker":"Podcast","text":"The report also went into detail on what sites people spent their time on."},{"start":194.79,"end":197.77,"speaker":"Podcast","text":"It showed time spent on webmail sites declined,"},{"start":198.27,"end":201.85,"speaker":"Podcast","text":"while social networking sites has shown a drastic increase."},{"start":202.49,"end":205.75,"speaker":"Podcast","text":"People are spending more time on social networking sites"},{"start":205.75,"end":211.15,"speaker":"Podcast","text":"and less time on email sites, and this is good news for social network sites."},{"start":212.36,"end":217.18,"speaker":"Podcast","text":"Last fall, Facebook founder Mark Zuckerberg predicted the death of email"},{"start":217.18,"end":220.52,"speaker":"Podcast","text":"when he introduced Facebook's new messaging interface."},{"start":221.74,"end":225.38,"speaker":"Podcast","text":"We don't think that a modern messaging system is going to be email."},{"start":226,"end":228.78,"speaker":"Podcast","text":"Zuckerberg said at a press conference in San Francisco,"},{"start":228.78,"end":233.4,"speaker":"Podcast","text":"Facebook users are now able to communicate through Facebook"},{"start":233.4,"end":236.84,"speaker":"Podcast","text":"via text, email or instant message,"},{"start":237.68,"end":243.02,"speaker":"Podcast","text":"and receive communications from all of these avenues through one news feed."},{"start":244.43,"end":249.21,"speaker":"Podcast","text":"Users typically value when related information from a variety of channels"},{"start":249.21,"end":251.93,"speaker":"Podcast","text":"is consolidated into one place,"},{"start":252.73,"end":257.19,"speaker":"Podcast","text":"and that's what Facebook's messaging interface is trying to accomplish for users."},{"start":258.09,"end":262.14,"speaker":"Podcast","text":"Many organizations with well-established IT departments"},{"start":262.53,"end":265.4,"speaker":"Podcast","text":"have typically hosted email in-house,"},{"start":266.12,"end":272.38,"speaker":"Podcast","text":"whereas others, as of lately, have turned to cloud email services, like Gmail."},{"start":273.58,"end":277.24,"speaker":"Podcast","text":"This switch is attractive, as it simply cuts costs."},{"start":278.28,"end":284.3,"speaker":"Podcast","text":"While many companies and large universities are making the switch to cloud-based email services,"},{"start":284.3,"end":289.86,"speaker":"Podcast","text":"will they make another shift towards using social networks to communicate?"},{"start":290.66,"end":296.88,"speaker":"Podcast","text":"One social networking system that businesses are turning to is called Collabro Chatter,"},{"start":297.46,"end":301.48,"speaker":"Podcast","text":"a business collaboration tool which describes itself"},{"start":301.48,"end":305.38,"speaker":"Podcast","text":"as an effective means of connecting with prospective customers."},{"start":306.66,"end":312.8,"speaker":"Podcast","text":"Collabro Chatter claims that by providing a system that puts businesses in easy contact"},{"start":312.8,"end":319.1,"speaker":"Podcast","text":"with potential customers, Collabro Chatter offers a genuine opportunity for companies"},{"start":319.1,"end":323,"speaker":"Podcast","text":"to advance office productivity and efficiency."},{"start":324.5,"end":331.52,"speaker":"Podcast","text":"And increased productivity and efficiency is music to any boss's ears, in these or any times."},{"start":333.36,"end":335.64,"speaker":"Podcast","text":"Well, that's it. What do you think, Roland?"},{"start":337.5,"end":342.6,"speaker":"Podcast","text":"He makes some good points, but I don't think email's going to disappear."},{"start":343.45,"end":346.87,"speaker":"Podcast","text":"I mean, people could maybe use less email,"},{"start":347.49,"end":352.31,"speaker":"Podcast","text":"but they'll still use it to receive more, like, personal messages."},{"start":353.27,"end":354.61,"speaker":"Podcast","text":"You know, private stuff."},{"start":355.33,"end":357.97,"speaker":"Podcast","text":"That's always going to be a big concern for people."},{"start":358.67,"end":359.93,"speaker":"Podcast","text":"You know, privacy."},{"start":360.71,"end":364.52,"speaker":"Podcast","text":"So, I don't know. I can't see it myself."},{"start":365.36,"end":369.06,"speaker":"Podcast","text":"I actually found what he said really, really interesting."},{"start":369.62,"end":372.82,"speaker":"Podcast","text":"I mean, doing business using social networking."},{"start":373.58,"end":374.72,"speaker":"Podcast","text":"Sounds like great fun."},{"start":375.22,"end":377.26,"speaker":"Podcast","text":"I might even go into business myself."},{"start":378.79,"end":380.61,"speaker":"Narrator","text":"That is the end of Task 4."},{"start":381.07,"end":384.63,"speaker":"Narrator","text":"You now have two minutes to complete your answers to Task 4"},{"start":384.63,"end":387.27,"speaker":"Podcast","text":"and to tidy up all your other answers."},{"start":509.76,"end":509.8,"speaker":"Podcast","text":"Art B."}]},"partB":[{"start":0,"end":0.52,"speaker":"Aline Li and Lionel Chan","text":"Art B."},{"start":1.66,"end":3.84,"speaker":"Narrator","text":"Open your data file at page 2."},{"start":5,"end":5.42,"speaker":"Narrator","text":"Situation."},{"start":6.5,"end":7.78,"speaker":"Aline Li and Lionel Chan","text":"You are Nicky Leung."},{"start":8.27,"end":10.08,"speaker":"Aline Li and Lionel Chan","text":"You work for Cultural Commons,"},{"start":10.6,"end":15.3,"speaker":"Aline Li and Lionel Chan","text":"which is a non-governmental organisation and NGO in Hong Kong."},{"start":16.26,"end":21.06,"speaker":"Aline Li and Lionel Chan","text":"Cultural Commons helps people from different countries who come to live in Hong Kong."},{"start":21.9,"end":25.7,"speaker":"Aline Li and Lionel Chan","text":"Your organisation is planning a fun day for a local community."},{"start":27.03,"end":31.21,"speaker":"Aline Li and Lionel Chan","text":"Your boss, Manjula Pillai, has asked you to do some tasks."},{"start":32.32,"end":36.7,"speaker":"Aline Li and Lionel Chan","text":"You will listen to a recording of the weekly podcast programme Bookmark."},{"start":37.3,"end":41.84,"speaker":"Aline Li and Lionel Chan","text":"In the podcast, you will hear an interview with author Lionel Chan."},{"start":43.59,"end":45.09,"speaker":"Aline Li and Lionel Chan","text":"Before the recording is played,"},{"start":45.63,"end":48.91,"speaker":"Aline Li and Lionel Chan","text":"you will have five minutes to study the question answer book"},{"start":48.91,"end":51.45,"speaker":"Aline Li and Lionel Chan","text":"and the data file for part B1"},{"start":52.24,"end":56.58,"speaker":"Aline Li and Lionel Chan","text":"and the question answer book and the data file for part B2."},{"start":57.59,"end":65.39,"speaker":"Aline Li and Lionel Chan","text":"Remember, you must choose to do the tasks in either part B1 or part B2."},{"start":65.39,"end":70.45,"speaker":"Aline Li and Lionel Chan","text":"Do not attempt both parts B1 and B2."},{"start":71.24,"end":75.56,"speaker":"Narrator","text":"Complete the tasks by following the instructions in the question answer book"},{"start":75.56,"end":77.44,"speaker":"Aline Li and Lionel Chan","text":"that you choose and on the recording."},{"start":78.37,"end":82.43,"speaker":"Aline Li and Lionel Chan","text":"You will find all the information you need in the question answer book"},{"start":82.43,"end":86.19,"speaker":"Aline Li and Lionel Chan","text":"and data file that you choose and on the recording."},{"start":87.16,"end":91.66,"speaker":"Aline Li and Lionel Chan","text":"As you listen, you can make notes on page 3 of the data file."},{"start":92.2,"end":95.44,"speaker":"Narrator","text":"You now have five minutes to familiarise yourself"},{"start":95.44,"end":99.64,"speaker":"Aline Li and Lionel Chan","text":"with the part B question answer book and the data file."},{"start":400.92,"end":402.6,"speaker":"Aline Li and Lionel Chan","text":"The recording is about to begin."},{"start":403.41,"end":405.85,"speaker":"Narrator","text":"Turn to page 3 of the data file."},{"start":412.65,"end":413.65,"speaker":"Aline Li and Lionel Chan","text":"I'm Aline Li."},{"start":414.21,"end":415.91,"speaker":"Aline Li and Lionel Chan","text":"Welcome to this week's Bookmark"},{"start":415.91,"end":420.15,"speaker":"Aline Li and Lionel Chan","text":"and we are delighted to have Lionel Chan as our special guest today."},{"start":420.81,"end":421.53,"speaker":"Aline Li and Lionel Chan","text":"Welcome, Lionel."},{"start":421.75,"end":422.55,"speaker":"Aline Li and Lionel Chan","text":"Thank you."},{"start":422.67,"end":423.75,"speaker":"Aline Li and Lionel Chan","text":"It's great to be here."},{"start":424.27,"end":426.53,"speaker":"Aline Li and Lionel Chan","text":"We are going to talk about your new book today."},{"start":426.83,"end":427.89,"speaker":"Aline Li and Lionel Chan","text":"But before we do that,"},{"start":428.15,"end":431.17,"speaker":"Aline Li and Lionel Chan","text":"I know you'd like to mention an important community event"},{"start":431.17,"end":432.37,"speaker":"Aline Li and Lionel Chan","text":"that's happening soon."},{"start":433.47,"end":433.95,"speaker":"Aline Li and Lionel Chan","text":"Okay, yeah."},{"start":434.51,"end":435.45,"speaker":"Aline Li and Lionel Chan","text":"It's a fun day."},{"start":436.15,"end":439.79,"speaker":"Aline Li and Lionel Chan","text":"And it's taking place in Kowloon Park on the 15th of April."},{"start":440.63,"end":443.19,"speaker":"Aline Li and Lionel Chan","text":"There'll be lots of people from different countries there."},{"start":443.84,"end":447.12,"speaker":"Aline Li and Lionel Chan","text":"Okay, so if we want to come along,"},{"start":447.34,"end":450.82,"speaker":"Aline Li and Lionel Chan","text":"we need to get down to Kowloon Park on the 15th of April."},{"start":451.44,"end":452.94,"speaker":"Aline Li and Lionel Chan","text":"Is that a Saturday or a Sunday?"},{"start":453.9,"end":456.16,"speaker":"Aline Li and Lionel Chan","text":"The 15th a Sunday, Arlene."},{"start":456.8,"end":457.18,"speaker":"Aline Li and Lionel Chan","text":"Right."},{"start":457.66,"end":459.72,"speaker":"Aline Li and Lionel Chan","text":"So what will be happening in the fun day?"},{"start":460.49,"end":464.15,"speaker":"Aline Li and Lionel Chan","text":"There'll be lots of activities, like a lucky draw."},{"start":465.17,"end":466.21,"speaker":"Aline Li and Lionel Chan","text":"I love lucky draws."},{"start":466.99,"end":469.41,"speaker":"Aline Li and Lionel Chan","text":"Yeah, but don't just come for the lucky draw."},{"start":470.09,"end":472.87,"speaker":"Aline Li and Lionel Chan","text":"I think the fun day is actually very important."},{"start":473.67,"end":477.95,"speaker":"Aline Li and Lionel Chan","text":"It's a great chance for people from different cultures to meet each other."},{"start":478.77,"end":482.73,"speaker":"Aline Li and Lionel Chan","text":"So a lucky draw and a chance to meet people from different cultures."},{"start":483.33,"end":483.97,"speaker":"Aline Li and Lionel Chan","text":"Sounds good."},{"start":484.69,"end":485.47,"speaker":"Aline Li and Lionel Chan","text":"And will you be there?"},{"start":486.01,"end":487.21,"speaker":"Aline Li and Lionel Chan","text":"Yeah, I'll be there."},{"start":487.67,"end":487.89,"speaker":"Aline Li and Lionel Chan","text":"Yeah."},{"start":488.61,"end":494.49,"speaker":"Aline Li and Lionel Chan","text":"Another one of the activities at the fun day is I'm giving a talk about body language."},{"start":495.15,"end":496.83,"speaker":"Aline Li and Lionel Chan","text":"A talk about body language?"},{"start":497.41,"end":499.81,"speaker":"Aline Li and Lionel Chan","text":"Is there much to say about body language then?"},{"start":500.31,"end":501.91,"speaker":"Aline Li and Lionel Chan","text":"Well, yeah, yes, there is."},{"start":502.63,"end":504.47,"speaker":"Aline Li and Lionel Chan","text":"We communicate using our bodies,"},{"start":505.21,"end":508.01,"speaker":"Aline Li and Lionel Chan","text":"and it's something we really should be more aware of."},{"start":508.49,"end":510.57,"speaker":"Aline Li and Lionel Chan","text":"Okay, like what, for example?"},{"start":511.25,"end":514.71,"speaker":"Aline Li and Lionel Chan","text":"Well, the classic example is eye contact."},{"start":515.43,"end":523.17,"speaker":"Aline Li and Lionel Chan","text":"Eye contact is the aspect of nonverbal communication that varies most from country to country."},{"start":523.59,"end":523.77,"speaker":"Aline Li and Lionel Chan","text":"Really?"},{"start":524.92,"end":529.62,"speaker":"Aline Li and Lionel Chan","text":"Yes, for example, the length of time that people's eyes meet."},{"start":530.4,"end":533.04,"speaker":"Aline Li and Lionel Chan","text":"If your eyes meet with someone for a long time,"},{"start":533.74,"end":538.04,"speaker":"Aline Li and Lionel Chan","text":"it can mean at least three different things depending on the country."},{"start":538.62,"end":539.72,"speaker":"Aline Li and Lionel Chan","text":"Three different things?"},{"start":540.22,"end":540.58,"speaker":"Aline Li and Lionel Chan","text":"Yeah."},{"start":541.33,"end":545.65,"speaker":"Aline Li and Lionel Chan","text":"For example, in some countries, it means you want to fight."},{"start":546.65,"end":550.21,"speaker":"Aline Li and Lionel Chan","text":"So too much eye contact can mean a sort of challenge, is that it?"},{"start":550.87,"end":556.17,"speaker":"Aline Li and Lionel Chan","text":"Well, yes, but in other countries, it can mean something totally different."},{"start":557.05,"end":562.63,"speaker":"Aline Li and Lionel Chan","text":"It can also mean that you are showing that you are really interested in what the person is saying."},{"start":563.41,"end":563.75,"speaker":"Aline Li and Lionel Chan","text":"Right."},{"start":564.13,"end":564.67,"speaker":"Aline Li and Lionel Chan","text":"And the third?"},{"start":565.39,"end":571.33,"speaker":"Aline Li and Lionel Chan","text":"Yes, well, the third possible meaning of the long meeting of the eyes is, of course,"},{"start":571.89,"end":575.45,"speaker":"Aline Li and Lionel Chan","text":"romantic, that you're interested in that person romantically."},{"start":576.63,"end":579.35,"speaker":"Aline Li and Lionel Chan","text":"Well, there's a bit of a difference there then."},{"start":579.79,"end":583.91,"speaker":"Aline Li and Lionel Chan","text":"You want to fight, you're interested, or you want to be his girlfriend."},{"start":584.37,"end":584.85,"speaker":"Aline Li and Lionel Chan","text":"Exactly."},{"start":585.99,"end":589.65,"speaker":"Aline Li and Lionel Chan","text":"And can you give me some advice to people about eye contact then?"},{"start":590.34,"end":597.35,"speaker":"Aline Li and Lionel Chan","text":"Well, I think the best advice is to try to become aware of what you do yourself and adapt to the"},{"start":597.35,"end":597.91,"speaker":"Narrator","text":"situation."},{"start":598.89,"end":600.09,"speaker":"Aline Li and Lionel Chan","text":"Sounds like good advice."},{"start":600.91,"end":605.69,"speaker":"Aline Li and Lionel Chan","text":"Become aware of what I do with my eyes and adapt to the situation I'm in."},{"start":606.27,"end":607.25,"speaker":"Aline Li and Lionel Chan","text":"Yes, that's it."},{"start":607.99,"end":608.97,"speaker":"Aline Li and Lionel Chan","text":"Now, I know."},{"start":609.43,"end":612.17,"speaker":"Aline Li and Lionel Chan","text":"We know that you'll be giving a talk at the fun day,"},{"start":612.55,"end":616.09,"speaker":"Aline Li and Lionel Chan","text":"but some of our listeners might not know that much about you."},{"start":616.63,"end":618.29,"speaker":"Aline Li and Lionel Chan","text":"Could you tell us something about yourself?"},{"start":619.01,"end":625.29,"speaker":"Aline Li and Lionel Chan","text":"Well, I was actually born in Singapore, but came here as a young man."},{"start":626.17,"end":630.85,"speaker":"Aline Li and Lionel Chan","text":"And when I first arrived in Hong Kong, I got a job as a social worker."},{"start":631.19,"end":631.71,"speaker":"Aline Li and Lionel Chan","text":"Oh, really?"},{"start":632.29,"end":634.59,"speaker":"Aline Li and Lionel Chan","text":"I always thought you were from Hong Kong."},{"start":635.03,"end":635.47,"speaker":"Aline Li and Lionel Chan","text":"No, no."},{"start":636.09,"end":636.27,"speaker":"Aline Li and Lionel Chan","text":"Singapore."},{"start":636.97,"end":638.21,"speaker":"Aline Li and Lionel Chan","text":"Okay, my mistake."},{"start":638.81,"end":640.71,"speaker":"Aline Li and Lionel Chan","text":"And how long were you a social worker?"},{"start":641.51,"end":644.23,"speaker":"Aline Li and Lionel Chan","text":"Oh, for about 10 years, I suppose."},{"start":644.95,"end":648.59,"speaker":"Aline Li and Lionel Chan","text":"Well, 10 years is quite a long time in a job like that."},{"start":649.77,"end":654.11,"speaker":"Aline Li and Lionel Chan","text":"I'm always interested to read what you have to say about communication barriers"},{"start":654.11,"end":655.89,"speaker":"Aline Li and Lionel Chan","text":"and how they affect us."},{"start":656.47,"end":661.09,"speaker":"Aline Li and Lionel Chan","text":"I'm interested to know what about those barriers that are particular to Hong Kong"},{"start":661.09,"end":665.67,"speaker":"Aline Li and Lionel Chan","text":"or barriers that are a real problem in Hong Kong compared to other places."},{"start":666.53,"end":669.09,"speaker":"Aline Li and Lionel Chan","text":"I'm not sure if these are unique to Hong Kong,"},{"start":669.47,"end":672.29,"speaker":"Aline Li and Lionel Chan","text":"but the barriers to communication that people mentioned"},{"start":672.29,"end":679.13,"speaker":"Aline Li and Lionel Chan","text":"when they've just arrived in Hong Kong are noise, time, and people not listening."},{"start":679.91,"end":681.49,"speaker":"Aline Li and Lionel Chan","text":"Yeah, I can imagine that."},{"start":682.45,"end":687.07,"speaker":"Aline Li and Lionel Chan","text":"Noise, time, and people not listening sounds like Hong Kong on a bad day."},{"start":687.89,"end":690.67,"speaker":"Aline Li and Lionel Chan","text":"Well, yes, it might be quite amusing,"},{"start":691.21,"end":694.93,"speaker":"Aline Li and Lionel Chan","text":"but these are all genuine barriers to communication in Hong Kong."},{"start":695.65,"end":697.63,"speaker":"Aline Li and Lionel Chan","text":"They all prevent communication."},{"start":698.27,"end":699.91,"speaker":"Aline Li and Lionel Chan","text":"And that's what a barrier is."},{"start":700.31,"end":703.31,"speaker":"Aline Li and Lionel Chan","text":"A barrier stops something from happening."},{"start":703.65,"end":708.67,"speaker":"Aline Li and Lionel Chan","text":"Okay, so a barrier stops something from happening, right?"},{"start":709.57,"end":712.49,"speaker":"Aline Li and Lionel Chan","text":"And the important thing is what happens next."},{"start":713.09,"end":717.19,"speaker":"Aline Li and Lionel Chan","text":"As I say, a barrier like noise stops communication happening."},{"start":717.75,"end":719.97,"speaker":"Aline Li and Lionel Chan","text":"But it's how that affects people."},{"start":720.47,"end":721.29,"speaker":"Aline Li and Lionel Chan","text":"That's the point."},{"start":722.28,"end":723.72,"speaker":"Aline Li and Lionel Chan","text":"Take noise as an example."},{"start":724.32,"end":726.66,"speaker":"Aline Li and Lionel Chan","text":"We all know Hong Kong can be very noisy."},{"start":727.28,"end":732.02,"speaker":"Aline Li and Lionel Chan","text":"But what happens when it's so, so noisy that we just can't communicate?"},{"start":732.86,"end":733.34,"speaker":"Aline Li and Lionel Chan","text":"I know."},{"start":733.62,"end":734.78,"speaker":"Aline Li and Lionel Chan","text":"I just get angry."},{"start":735.28,"end":736.86,"speaker":"Aline Li and Lionel Chan","text":"Well, you're not alone, Arlene."},{"start":737.72,"end":740.72,"speaker":"Aline Li and Lionel Chan","text":"There's been quite a lot of research into this area,"},{"start":741.12,"end":744.44,"speaker":"Aline Li and Lionel Chan","text":"you know, monitoring people's blood pressure and so on."},{"start":744.96,"end":749.5,"speaker":"Aline Li and Lionel Chan","text":"And all the research points towards noise as a communication barrier"},{"start":749.5,"end":753.08,"speaker":"Aline Li and Lionel Chan","text":"adding significantly to people's stress levels."},{"start":753.08,"end":757.22,"speaker":"Aline Li and Lionel Chan","text":"Okay, I'll have to look for a quiet space to talk then."},{"start":758.7,"end":761.34,"speaker":"Aline Li and Lionel Chan","text":"You mentioned newcomers arriving in Hong Kong."},{"start":761.92,"end":763.68,"speaker":"Aline Li and Lionel Chan","text":"You mean people from outside China?"},{"start":764.5,"end":768.1,"speaker":"Aline Li and Lionel Chan","text":"Yes, well, the people I meet in Hong Kong are from everywhere,"},{"start":768.64,"end":772.94,"speaker":"Aline Li and Lionel Chan","text":"from Africa, from South America, from the Middle East."},{"start":773.74,"end":777.78,"speaker":"Aline Li and Lionel Chan","text":"These people come to Hong Kong to start new lives, just like I did."},{"start":778.6,"end":781.68,"speaker":"Aline Li and Lionel Chan","text":"Some people need help to deal with the practical difficulties."},{"start":782.4,"end":785.16,"speaker":"Aline Li and Lionel Chan","text":"What kinds of difficulties do they need help with?"},{"start":785.9,"end":788.38,"speaker":"Aline Li and Lionel Chan","text":"Well, things like finding schools for their children."},{"start":789.08,"end":790.56,"speaker":"Aline Li and Lionel Chan","text":"There are two difficulties here."},{"start":791.34,"end":796.68,"speaker":"Aline Li and Lionel Chan","text":"Firstly, to find a school, and secondly, to fill in the school application form."},{"start":797.52,"end":801.4,"speaker":"Aline Li and Lionel Chan","text":"Some newcomers don't really have the written skills in English or Chinese"},{"start":801.4,"end":804.48,"speaker":"Aline Li and Lionel Chan","text":"to fill in those long government forms."},{"start":805.08,"end":808.86,"speaker":"Aline Li and Lionel Chan","text":"Yeah, well, I find filling in those forms bad enough."},{"start":808.86,"end":813.5,"speaker":"Aline Li and Lionel Chan","text":"But if it's something as important as finding a school for their children,"},{"start":814.06,"end":817.24,"speaker":"Aline Li and Lionel Chan","text":"then that sounds like something really worthwhile to do."},{"start":818.17,"end":824.25,"speaker":"Aline Li and Lionel Chan","text":"Okay, oh, before I forget, we need to give our listeners some information about your new book."},{"start":824.83,"end":827.07,"speaker":"Aline Li and Lionel Chan","text":"It's called An Immigrant's Song."},{"start":827.87,"end":829.09,"speaker":"Aline Li and Lionel Chan","text":"And where can we buy it?"},{"start":829.63,"end":833.31,"speaker":"Aline Li and Lionel Chan","text":"It's available in all major bookstores in Hong Kong."},{"start":833.95,"end":836.41,"speaker":"Aline Li and Lionel Chan","text":"All big bookstores in Hong Kong."},{"start":836.97,"end":837.63,"speaker":"Aline Li and Lionel Chan","text":"Anywhere else?"},{"start":837.63,"end":843.19,"speaker":"Aline Li and Lionel Chan","text":"Yes, and of course, at the fun day at Kowloon Park on April 15th."},{"start":843.33,"end":846.19,"speaker":"Aline Li and Lionel Chan","text":"Oh, yes, of course, at the fun day as well."},{"start":846.99,"end":850.33,"speaker":"Aline Li and Lionel Chan","text":"Well, I'd recommend all our listeners to give it a try."},{"start":850.97,"end":852.55,"speaker":"Aline Li and Lionel Chan","text":"It really is a good read."},{"start":853.25,"end":856.21,"speaker":"Aline Li and Lionel Chan","text":"Well, Lionel, it's been very nice to meet you,"},{"start":856.47,"end":858.45,"speaker":"Aline Li and Lionel Chan","text":"and thanks for coming into the pod today."},{"start":859.55,"end":862.93,"speaker":"Narrator","text":"That is the end of the listening component of this test."},{"start":863.51,"end":871.85,"speaker":"Aline Li and Lionel Chan","text":"You will have 1 hour and 15 minutes to complete the written tasks in either Part B1 or Part B2."},{"start":872.6,"end":875.4,"speaker":"Aline Li and Lionel Chan","text":"An announcement will be made when time is up."},{"start":876.36,"end":879.56,"speaker":"Aline Li and Lionel Chan","text":"Take off your earphones now and turn off your radio."}]});})();
